-- Explicit scenario-to-coverage mapping prevents key-name coupling.
alter table public.autonomous_qa_scenarios add column if not exists coverage_key text;
update public.autonomous_qa_scenarios set coverage_key=scenario_key where scenario_key in('provider-radius','gps-geofence','service-lifecycle','permissions-rls','payments','realtime','roles');
update public.autonomous_qa_scenarios set coverage_key='permissions-rls' where scenario_key='permissions-rls';
create or replace function public.superadmin_run_qa_scenario(p_scenario_id uuid,p_simulator_results jsonb,p_chaos_result jsonb default '{}'::jsonb)
returns public.autonomous_qa_runs language plpgsql security definer set search_path=public,private,auth as $$
declare s public.autonomous_qa_scenarios%rowtype;r public.autonomous_qa_runs%rowtype;passed boolean;missing text[]:='{}';expected jsonb;begin if auth.uid() is null or not private.is_superadmin()then raise exception 'SUPERADMIN_REQUIRED' using errcode='42501';end if;select * into s from public.autonomous_qa_scenarios where id=p_scenario_id and status='ACTIVE';if s.id is null then raise exception 'ACTIVE_SCENARIO_REQUIRED';end if;expected:=coalesce(s.deterministic_judge->'required_assertions','[]'::jsonb);select coalesce(array_agg(x),'{}')into missing from jsonb_array_elements_text(expected)x where coalesce((p_simulator_results->>x)::boolean,false)=false;passed:=cardinality(missing)=0 and not coalesce((p_chaos_result->>'unexpected_failure')::boolean,false);
 insert into public.autonomous_qa_runs(scenario_id,status,simulator_results,chaos_result,judge_result,diagnosis,remediation_request,permanent_regression,started_at,finished_at)values(s.id,case when passed then'PASSED'else'FAILED'end,coalesce(p_simulator_results,'{}'),coalesce(p_chaos_result,'{}'),jsonb_build_object('passed',passed,'missing_assertions',to_jsonb(missing),'seeded_defect',s.seeded_defect),case when passed then null else'Deterministic judge rejected scenario'end,case when passed then null else'Remediate failed assertions and rerun before release'end,passed and s.source_type='REGRESSION',now(),now())returning * into r;
 if s.coverage_key is not null then update public.autonomous_quality_coverage set scenario_id=s.id,last_run_id=r.id,status=case when passed then'COVERED'else'FAILING'end,updated_at=now() where coverage_key=s.coverage_key;end if;return r;end$$;